1	export type Cell = [number, number];
2	
3	export function nextGeneration(liveCells: Cell[]): Cell[] {
4	  return candidates(liveCells).filter((cell) =>
5	    survivesOrIsBorn(cell, liveCells),
6	  );
7	}
8	
9	function survivesOrIsBorn(cell: Cell, liveCells: Cell[]): boolean {
10	  const neighbors = countLiveNeighbors(cell, liveCells);
11	  if (isAlive(cell, liveCells)) return neighbors === 2 || neighbors === 3;
12	  return neighbors === 3;
13	}
