15	function candidates(liveCells: Cell[]): Cell[] {
16	  const seen = new Map<string, Cell>();
17	  for (const [x, y] of liveCells) {
18	    for (let dx = -1; dx <= 1; dx++) {
19	      for (let dy = -1; dy <= 1; dy++) {
20	        const candidate: Cell = [x + dx, y + dy];
21	        seen.set(key(candidate), candidate);
22	      }
23	    }
24	  }
25	  return [...seen.values()];
26	}
27	
28	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
29	  return liveCells.some((other) => key(other) === key(cell));
30	}
31	
32	function key([x, y]: Cell): string {
33	  return `${x},${y}`;
34	}
35	
36	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
37	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
38	}
39	
40	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
41	  const isSameCell = x === otherX && y === otherY;
42	  const isAdjacent =
43	    isWithinOneStep(x, otherX) && isWithinOneStep(y, otherY);
44	  return isAdjacent && !isSameCell;
45	}
46	
47	function isWithinOneStep(coordinate: number, other: number): boolean {
48	  return Math.abs(coordinate - other) <= 1;
49	}
